parameters.functionCode:
// Extract key fields from the incoming Gmail message
const message = items[0].json;

const from = message.payload?.headers?.find(h => h.name === 'From')?.value || '';
const subject = message.payload?.headers?.find(h => h.name === 'Subject')?.value || '';
const messageId = message.id || '';
const threadId = message.threadId || '';
const timestamp = new Date(parseInt(message.internalDate)).toISOString();

// Use snippet as the body text (plain-text preview)
const body = message.snippet || '';

return [
  {
    json: {
      from,
      subject,
      body,
      threadId,
      messageId,
      timestamp
    }
  }
];

// Parse Claude's response, splitting on ---REPLY--- and ---META--- markers
const content = items[0].json.content;
const text = Array.isArray(content)
  ? content.map(c => c.text).join('')
  : (typeof content === 'string' ? content : '');

const previous = items[0].json;

let replyText = text;
let action = 'reply_only';
let meta = {};

// Split on markers
const replyMatch = text.split('---REPLY---');
if (replyMatch.length > 1) {
  replyText = replyMatch[1];
}

const metaMatch = text.split('---META---');
if (metaMatch.length > 1) {
  const metaRaw = metaMatch[1].trim();
  // Trim replyText to remove everything after ---META---
  replyText = replyText.split('---META---')[0].trim();
  try {
    meta = JSON.parse(metaRaw);
    action = meta.action || 'reply_only';
  } catch (e) {
    // If JSON parse fails, default to reply_only
    action = 'reply_only';
  }
}

// Carry forward the original email fields from the upstream node
return [
  {
    json: {
      replyText,
      action,
      meta,
      from: $('Extract Email').first().json.from,
      subject: $('Extract Email').first().json.subject,
      body: $('Extract Email').first().json.body,
      threadId: $('Extract Email').first().json.threadId,
      messageId: $('Extract Email').first().json.messageId,
      timestamp: $('Extract Email').first().json.timestamp
    }
  }
];

